 private static final AtomicLong IDS=new AtomicLong(SystemClock.elapsedRealtimeNanos()),LATEST=new AtomicLong();private static final AtomicReference<Session> PENDING_RECORD=new AtomicReference<>();
 private static final ArrayBlockingQueue<Session> CLOSED_EVENTS=new ArrayBlockingQueue<>(16);
 private static final AtomicBoolean DRAINING=new AtomicBoolean();private static final AtomicLong DROPPED_EVENTS=new AtomicLong();
 private static final ThreadPoolExecutor RECORD_IO=new ThreadPoolExecutor(0,1,1,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"YOnLiveRecords");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private static void scheduleRecords(){if(!DRAINING.compareAndSet(false,true))return;try{RECORD_IO.execute(LiveActivity::drainRecords);}catch(RejectedExecutionException e){DRAINING.set(false);android.util.Log.e("YOn","live_record_queue",e);}}
 private static void drainRecords(){try{for(;;){Session state=PENDING_RECORD.getAndSet(null);if(state!=null)state.writeRecord();Session closed=CLOSED_EVENTS.poll();if(closed!=null)closed.writeClosedEvent();if(PENDING_RECORD.get()==null&&CLOSED_EVENTS.isEmpty())break;}}finally{DRAINING.set(false);if(PENDING_RECORD.get()!=null||!CLOSED_EVENTS.isEmpty())scheduleRecords();}}

