 private static final class Counters {
  final Analytics.Flow flow=new Analytics.Flow();final Analytics.Drive drive=new Analytics.Drive();final Analytics.Visitors visitors=new Analytics.Visitors();long owner;boolean preserve=true;
  synchronized void policy(boolean keep){preserve=keep;}
  synchronized void claim(long id){if(!preserve)resetCounts();owner=id;}
  synchronized void release(long id){if(owner!=id)return;owner=0;if(preserve){flow.pause();drive.pause();visitors.pause();}else resetCounts();}
  synchronized void resetCounts(){flow.reset();drive.resetCounts();visitors.reset();}
 }
