 private void readCameraChoices(){try{android.hardware.camera2.CameraManager cameras=(android.hardware.camera2.CameraManager)getSystemService(CAMERA_SERVICE);for(String id:cameras.getCameraIdList()){Integer facing=cameras.getCameraCharacteristics(id).get(android.hardware.camera2.CameraCharacteristics.LENS_FACING);if(facing==null)continue;if(facing==android.hardware.camera2.CameraCharacteristics.LENS_FACING_FRONT&&frontCameraId==null)frontCameraId=id;if(facing==android.hardware.camera2.CameraCharacteristics.LENS_FACING_BACK&&backCameraId==null)backCameraId=id;}}catch(Exception ignored){}updateCameraSwitch();}
 private boolean frontSelected(){String chosen=getSharedPreferences("YOn",0).getString("cameraId","");if(chosen.equals(frontCameraId))return true;if(chosen.equals(backCameraId))return false;return getSharedPreferences("YOn",0).getString("cameraFacing",android.os.Build.MODEL.equalsIgnoreCase("aikit")?"front":"back").equals("front");}
 private void updateCameraSwitch(){boolean available=frontCameraId!=null&&backCameraId!=null;cameraSwitch.setEnabled(available);cameraSwitch.setText(available?(frontSelected()?"후면으로 전환":"전면으로 전환"):"카메라 전환");cameraSwitch.setContentDescription(available?(frontSelected()?"전면 카메라 사용 중, 후면 카메라로 전환":"후면 카메라 사용 중, 전면 카메라로 전환"):"전환할 카메라 없음");}
 private void switchCamera(){if(frontCameraId==null||backCameraId==null)return;boolean toFront=!frontSelected();getSharedPreferences("YOn",0).edit().putString("cameraId",toFront?frontCameraId:backCameraId).putString("cameraFacing",toFront?"front":"back").apply();updateCameraSwitch();stopCurrent("CAMERA_SWITCH");if(wantsRunning)begin();else status.setText("일시정지 · "+(toFront?"전면 카메라":"후면 카메라"));}
