 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if((request!=CAPTURE&&request!=502)||result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null){String value=data.getStringExtra("photo_uri");if(value!=null)uri=Uri.parse(value);}if(uri==null||!"content".equals(uri.getScheme()))return;try{startActivity(new Intent().setClassName(this,"com.yonlab.vision.PhotoActivity").setDataAndType(uri,"image/*").putExtra("input_uri",uri.toString()).putExtra("mode",mode).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(ActivityNotFoundException e){Ui.error(this,"사진을 열 수 없습니다",e);}}
