 @Override protected void onResume(){super.onResume();active=true;updateCameraSwitch();if(!wantsRunning)status.setText("일시정지");begin();}
 @Override protected void onPause(){active=false;releaseTone();alertRaised=false;stopCurrent("BACKGROUND");super.onPause();}
 @Override protected void onDestroy(){active=false;stopCurrent("DESTROYED");super.onDestroy();}
 @Override protected void onSaveInstanceState(Bundle out){out.putBoolean("running",wantsRunning);super.onSaveInstanceState(out);}
 private void alert(Session owner){Analytics.DriveSnapshot d=owner.drive.snapshot();boolean raised=d.facePresent&&(d.drowsy||d.lookingAway);long now=SystemClock.elapsedRealtime();if(raised&&!alertRaised&&alertSound&&(lastAlertAt==0||now-lastAlertAt>=5000)){try{if(tone==null)tone=new ToneGenerator(AudioManager.STREAM_NOTIFICATION,45);if(tone.startTone(ToneGenerator.TONE_PROP_BEEP,180)){lastAlertAt=now;owner.alertTones++;}}catch(RuntimeException ignored){releaseTone();}}alertRaised=raised;}
 private void releaseTone(){if(tone!=null){tone.release();tone=null;}}
 private void visitorSettings(){LinearLayout panel=Ui.column(this);panel.addView(Ui.text(this,"매칭 기준",15));Spinner threshold=new Spinner(this);threshold.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"넓게 · 0.30","기본 · 0.363","엄격하게 · 0.45"}));float saved=getSharedPreferences("YOn",0).getFloat("visitorThreshold",Registry.DEFAULT_THRESHOLD);threshold.setSelection(saved<.33f?0:saved>.40f?2:1);panel.addView(threshold);panel.addView(Ui.text(this,"방문 기록 유지",15));Spinner ttl=new Spinner(this);ttl.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"1시간","24시간","7일"}));long period=getSharedPreferences("YOn",0).getLong("visitorTtlMs",86400000L);ttl.setSelection(period<=3600000?0:period>86400000?2:1);panel.addView(ttl);new android.app.AlertDialog.Builder(this).setTitle("방문 설정").setView(panel).setPositiveButton("적용",(d,w)->{getSharedPreferences("YOn",0).edit().putFloat("visitorThreshold",new float[]{.30f,Registry.DEFAULT_THRESHOLD,.45f}[threshold.getSelectedItemPosition()]).putLong("visitorTtlMs",new long[]{3600000L,86400000L,604800000L}[ttl.getSelectedItemPosition()]).apply();stopCurrent("VISITOR_SETTINGS");begin();}).setNegativeButton("닫기",null).show();}
