 private void renderExpressions(ExpressionPolicy.Snapshot snapshot,AgeGenderPolicy.Snapshot audience){
  if(expressionBars==null)return;expressionSummary.setText(snapshot.evaluated==0?"얼굴을 맞춰주세요":"평균 확률 · "+snapshot.evaluated+"명");StringBuilder joint=new StringBuilder();
  for(int i=0;i<ExpressionPolicy.CLASSES;i++){expressionBars[i].setProgress(Math.round(snapshot.meanProbabilities[i]*1000));expressionValues[i].setText(snapshot.evaluated==0?"—":Math.round(snapshot.meanProbabilities[i]*100)+"%");for(int smile=0;smile<3;smile++)if(snapshot.smileJoint[i][smile]>0){if(joint.length()>0)joint.append(" · ");joint.append(ExpressionPolicy.korean(i)).append(smile==0?"·미소 ":smile==1?"·미소 없음 ":"·미소 미확인 ").append(snapshot.smileJoint[i][smile]).append("명");}}
  expressionJoint.setText(joint.toString());
  StringBuilder age=new StringBuilder();for(int i=0;i<3;i++)if(audience.ageCounts[i]>0){if(age.length()>0)age.append(" · ");age.append(AgeGenderPolicy.ageGroupLabel(i)).append(' ').append(audience.ageCounts[i]).append("명");}if(audience.genders>0){if(age.length()>0)age.append("\n");age.append("성별 평균 · 여성 ").append(Math.round(audience.genderMean[0]*100)).append("% · 남성 ").append(Math.round(audience.genderMean[1]*100)).append('%');}ageGenderDetails.setText(age.toString());
  StringBuilder combinations=new StringBuilder();for(int a=0;a<3;a++)for(int g=0;g<2;g++)for(int e=0;e<7;e++)if(audience.combinations[a][g][e]>0){if(combinations.length()>0)combinations.append(" · ");combinations.append(AgeGenderPolicy.ageGroupLabel(a)).append('·').append(AgeGenderPolicy.genderLabel(g)).append('·').append(ExpressionPolicy.korean(e)).append(' ').append(audience.combinations[a][g][e]).append("명");}combinationDetails.setText(combinations.length()==0?"":"조합 · "+combinations);

 }
 private static JSONObject expressionJson(ExpressionPolicy.Snapshot snapshot,double milliseconds,int evaluated)throws JSONException{
  JSONArray counts=new JSONArray(),mean=new JSONArray(),joint=new JSONArray();for(int i=0;i<ExpressionPolicy.CLASSES;i++){counts.put(snapshot.counts[i]);mean.put((double)snapshot.meanProbabilities[i]);JSONArray row=new JSONArray();for(int n:snapshot.smileJoint[i])row.put(n);joint.put(row);}
  return new JSONObject().put("scope","CURRENT_FRAME").put("modelSha256",FaceEngine.EXPRESSION_SHA256).put("visible",snapshot.visible).put("evaluated",snapshot.evaluated).put("missing",snapshot.missing).put("inferenceFaces",evaluated).put("maxFaces",FaceEngine.MAX_EXPRESSION_FACES).put("inferenceMs",milliseconds).put("classCounts",counts).put("meanProbabilities",mean).put("smileJointCounts",joint);
 }
 private static boolean finite(float x){return !Float.isNaN(x)&&!Float.isInfinite(x);}
 private static Object jsonFloat(float x){return finite(x)?(double)x:JSONObject.NULL;}
 private static int[] argb(BgrFrame f){if(f.width>f.height)return CapturePixels.argb(f.data,f.width,f.height,false);long pixels=(long)f.width*f.height;if(f.width<1||f.height<1||pixels>Integer.MAX_VALUE/3||f.data.length!=pixels*3)throw new IllegalArgumentException("frame");int[] rgb=new int[(int)pixels];for(int i=0,j=0;i<rgb.length;i++,j+=3)rgb[i]=0xff000000|((f.data[j+2]&255)<<16)|((f.data[j+1]&255)<<8)|(f.data[j]&255);return rgb;}
